function headerV3(){return `<div class="announcement announce-v2"><span>${offers[1]} · ${offers[4]}</span></div><header class="header header-v2"><button class="icon-btn mobile-menu" data-menu aria-label="Open menu" aria-expanded="false" aria-controls="lux-menu">${icons.menu}</button><nav class="nav nav-v2" aria-label="Primary navigation">${link('/','Home')}${link('/shop','Shop')}${link('/collection','The Collection')}${link('/about','Our Story')}${link('/the-sixth-ritu','The Sixth Ritu')}${link('/contact','Contact')}</nav><a class="brand brand-v2" href="/" data-link><img src="/logo.png" alt="The Sixth Ritu" /></a><div class="tools"><button class="icon-btn" data-search aria-label="Search">${icons.search}</button>${link('/account',icons.user,'icon-btn desktop-tool')}<button class="icon-btn desktop-tool" data-wishlist aria-label="Wishlist">${icons.heart}</button><button class="icon-btn" data-cart aria-label="Bag">${icons.bag}<span class="count">${cart.reduce((a,i)=>a+i.qty,0)}</span></button></div></header><aside class="menu-panel luxury-drawer" id="lux-menu" aria-label="Mobile navigation" aria-hidden="true"><div class="drawer-main"><div class="drawer-top"><div><img src="/logo.png" alt="The Sixth Ritu"/><p>THE SEASON OF LUXURY</p></div><button class="lux-close" data-menu-close aria-label="Close menu">×</button></div><div class="drawer-nav-label"><span>NAVIGATION</span><i></i></div><nav class="lux-drawer-nav">${drawerRow('/','Home','home')}${drawerRow('/shop','Shop','shop')}${drawerRow('/collection','The Collection','collection')}${drawerRow('/about','Our Story','story')}${drawerRow('/the-sixth-ritu','The Sixth Ritu','ritu')}${drawerRow('/contact','Contact','contact')}</nav><div class="drawer-secondary">${drawerRow('/wishlist','Wishlist','heart')}<button class="lux-drawer-row" data-drawer-bag><span class="drawer-row-icon">${drawerIcons.bag}</span><span>Bag <em>${cart.reduce((a,i)=>a+i.qty,0)}</em></span><b>›</b></button></div><div class="drawer-bottom"><p>MORE THAN A FRAGRANCE.<br/><strong>A HIGHER SEASON.</strong></p><div class="drawer-emblem"><i></i><span>✾</span><i></i></div><div class="drawer-social" role="group" aria-label="Social channels"><button data-social aria-label="Instagram">◎</button><button data-social aria-label="Facebook">f</button><button data-social aria-label="YouTube">▶</button><button data-social aria-label="Pinterest">p</button></div></div></div><div class="drawer-visual"><img src="/hero banner 3.png" alt="Golden Ritual fragrance scene"/><div class="drawer-visual-words">SCENTS <b>◇</b> MEMORIES <b>◇</b> RITUALS <b>◇</b> BEYOND<br/>SEASONS</div><div class="drawer-visual-line"></div><div class="drawer-visual-brand">THE SIXTH RITU<br/><span>THE SEASON<br/>OF LUXURY</span></div></div></aside>`}
function footerV2(){return `<section class="newsletter newsletter-v2 section" id="newsletter"><div class="container newsletter-v2-grid"><div class="newsletter-mark"><img src="/logo.png" alt="The Sixth Ritu"/><p class="eyebrow">Enter the world of The Sixth Ritu</p><h2 class="display">Stay in<br/>the Season.</h2></div><div class="newsletter-form"><p>Be the first to discover new creations, private releases and stories from The Sixth Ritu.</p><form class="email-form" data-newsletter><input aria-label="Your email address" type="email" placeholder="Your Email Address" required/><button>Join the Season →</button></form><p class="form-note">By subscribing, you agree to receive communications from The Sixth Ritu.</p></div></div></section><footer class="footer footer-v2"><div class="container"><div class="footer-brand-hero"><img src="/logo.png" alt="The Sixth Ritu"/><span>The Season of Luxury</span></div><div class="footer-top"><div class="footer-brand"><p>Fragrances inspired by emotion, created to become memory.</p></div><div><h3>Shop</h3>${products.map(p=>link('/product/'+p.slug,p.name)).join('')}</div><div><h3>Discover</h3>${link('/about','Our Story')}${link('/the-sixth-ritu','The Sixth Ritu')}${link('/collection','The Collection')}${link('/contact','Contact Us')}</div><div><h3>Customer Care</h3>${link('/shipping','Shipping & Delivery')}${link('/returns','Returns & Exchanges')}${link('/faq','FAQs')}${link('/track-order','Track Order')}</div></div><div class="footer-bottom"><span>© 2026 The Sixth Ritu. All Rights Reserved.</span><span>${link('/privacy','Privacy')} &nbsp; ${link('/terms','Terms')} &nbsp; Instagram</span></div></div></footer>`}
function newProductStage(){let p=products[0];return `<section class="collection-stage section" id="collection-stage" style="--stage:${p.accent}"><div class="container"><div class="stage-kicker"><p class="eyebrow">The Signature Collection</p><p>Six Fragrances. Six Stories.</p></div><div class="stage-layout"><div class="stage-copy"><span class="stage-number">01 / 06</span><p class="notes">${p.notes}</p><h2 class="display">${p.name}</h2><h3>${p.subtitle}</h3><p class="stage-description">${p.description}</p>${link('/product/'+p.slug,'Explore '+p.name,'text-link')}</div><div class="stage-product"><div class="stage-orbit"></div><img src="${p.image}" alt="${p.name} fragrance"/></div></div><div class="stage-nav">${products.map((x,i)=>`<button class="${i===0?'active':''}" data-stage="${i}"><span>${String(i+1).padStart(2,'0')}</span>${x.name}</button>`).join('')}</div></div></section>`}
function rituSelector(){let p=products[0];return `<section class="ritu-selector" id="find"><div class="container ritu-grid"><div class="ritu-list"><p class="eyebrow">Choose by Mood</p><h2 class="display">What Is Your<br/>Ritu Today?</h2><p class="ritu-prompt">I want something...</p>${products.map((x,i)=>`<button class="ritu-choice ${i===0?'active':''}" data-ritu="${i}"><span>${x.mood}</span><small>${x.character}</small></button>`).join('')}</div><div class="ritu-product"><div class="ritu-wash"></div><img src="${p.image}" alt="${p.name} fragrance"/><div class="ritu-caption"><p class="eyebrow">Your Ritu</p><h3>${p.name}</h3><p>${p.character}</p>${link('/product/'+p.slug,'Find Your Fragrance','inline-link')}</div></div></div></section>`}
function seasonsV2(){const seasons=[['VASANTA','New Beginnings'],['GRISHMA','Heat & Radiance'],['VARSHA','Rain & Renewal'],['SHARAD','Clarity'],['HEMANTA','Golden Warmth'],['SHISHIRA','Stillness']];return `<section class="seasons-v2"><div class="season-pin"><div class="season-head"><p class="eyebrow">The Inspiration</p><p>India Knows Six Seasons.</p></div><div class="season-steps">${seasons.map((s,i)=>`<article class="season-step ${i===0?'active':''}" data-season="${i}"><span>${String(i+1).padStart(2,'0')}</span><h2 class="display">${s[0]}</h2><p>${s[1]}</p></article>`).join('')}</div><div class="season-final-v2"><p>And Then, There Is One More.</p><h2 class="display">THE SIXTH RITU</h2><span>The Season of Luxury</span></div></div></section>`}
function homeV2(){return `<main id="main" class="page-enter"><section class="banner-hero" aria-label="Featured fragrances">${banners.map((b,i)=>`<a href="/product/${b.slug}" data-link class="banner-slide ${i===0?'active':''}" data-banner-slide="${i}" aria-label="Explore ${b.label}"><picture><source media="(max-width: 640px)" srcset="${b.mobile}"><img src="${b.desktop}" alt="${b.label} campaign" ${i===0?'fetchpriority="high"':''}/></picture></a>`).join('')}<div class="banner-controls"><button data-slide-prev aria-label="Previous campaign">←</button><div class="banner-dots">${banners.map((b,i)=>`<button class="${i===0?'active':''}" data-slide="${i}" aria-label="Show ${b.label}"></button>`).join('')}</div><button data-slide-next aria-label="Next campaign">→</button></div></section><section class="offer-marquee" aria-label="Current offers"><div class="marquee-track">${[...offers,...offers].map(o=>`<span>${o}</span><b>✦</b>`).join('')}</div></section><section class="journey-intro section"><div class="container journey-grid"><div class="journey-title reveal"><p class="eyebrow">Welcome to The Sixth Ritu</p><h2 class="display">Some Seasons<br/>Change the World.<br/><i>Others Stay With You.</i></h2></div><div class="journey-image reveal"><img src="/hero banner 2.png" alt="Dark Monsoon campaign" loading="lazy"/></div><div class="journey-copy reveal"><p>India has always known six seasons — Vasanta, Grishma, Varsha, Sharad, Hemanta and Shishira. Each transforms the world around us and leaves behind a feeling.</p><p>We imagine another. A season found in the scent of rain after a storm, the warmth of an evening ritual, flowers resting on silk, or the memory of someone after they have gone.</p>${link('/about','Discover Our Story','text-link')}</div></div></section>${newProductStage()}${rituSelector()}${seasonsV2()}<section class="memory-campaign"><img src="/hero banner 4.png" alt="Flora Silk campaign" loading="lazy"/><div class="memory-copy"><p class="eyebrow">The Sixth Ritu</p><h2 class="display">A Memory<br/>Has No<br/>Season.</h2>${link('/collection','Explore The Collection','btn')}</div></section><section class="character-showcase section"><div class="container"><div class="section-head"><div><p class="eyebrow">Shop by Character</p><h2 class="display">Find a Fragrance That Feels Like You.</h2></div></div><div class="character-track">${products.map(p=>`<a href="/product/${p.slug}" data-link class="character-tile" style="--tile:${p.accent}"><img src="${p.image}" alt="${p.name}" loading="lazy"/><div><p>${p.character}</p><h3 class="display">${p.mood}</h3><span>Explore ${p.name} →</span></div></a>`).join('')}</div></div></section><section class="art-v2 section"><div class="container art-v2-grid"><div class="art-visual"><img src="/hero banner 3.png" alt="Golden Ritual campaign" loading="lazy"/></div><div class="art-copy reveal"><p class="eyebrow">The Art of Fragrance</p><h2 class="display">More Than a Fragrance.<br/>A Personal Ritual.</h2><p>A fragrance becomes meaningful through the moments connected to it. A first impression. A familiar evening. A celebration. A journey. A person.</p><div class="art-words">MEMORY<br/>RITUAL<br/>SCENT</div></div></div></section><section class="product-showcase section"><div class="container"><div class="section-head"><div><p class="eyebrow">The Collection</p><h2 class="display">Six expressions of one idea.</h2></div>${link('/shop','Shop All','text-link')}</div><div class="product-grid reveal-grid">${products.map(productCard).join('')}</div></div></section><section class="quote-v2"><div class="quote-line"></div><blockquote>“We do not create fragrances merely to be worn.<br/>We create them to be remembered.”</blockquote><cite>— The Sixth Ritu</cite></section><section class="social-v2 section"><div class="container"><div class="social-v2-head"><div><p class="eyebrow">Follow the Season</p><h2 class="display">@TheSixthRitu</h2></div><a href="#newsletter" class="text-link">Follow Our Journey</a></div></div><div class="social-ticker">${[...products,...products].map(p=>`<div><img src="${p.image}" alt="${p.name}" loading="lazy"/><span>${p.name}</span></div>`).join('')}</div></section></main>`}
function render(){let content;if(route==='/'||route==='/index.html')content=homeV2();else if(route==='/shop')content=shop();else if(route==='/collection')content=collection();else if(route==='/about')content=narrative('about');else if(route==='/the-sixth-ritu')content=narrative('ritu');else if(route==='/contact')content=contact();else if(route==='/search')content=searchPage();else if(route==='/wishlist')content=wishlistPage();else if(route==='/cart')content=cartPage();else if(route==='/checkout')content=checkout();else if(route==='/account'||route==='/account/orders'||route==='/track-order')content=route==='/track-order'?supportPage('Track your order.','Order tracking will appear here once the fulfillment service is connected.'):account();else if(route==='/faq')content=faq();else if(['/shipping','/returns','/privacy','/terms'].includes(route))content=supportPage(({ '/shipping':'Shipping & Delivery','/returns':'Returns & Exchanges','/privacy':'Privacy Policy','/terms':'Terms & Conditions'})[route],'Details will be added once confirmed by The Sixth Ritu.');else if(route.startsWith('/product/'))content=productPage(bySlug(route.split('/').pop()));else content=notFound();app.innerHTML=headerV2()+content+footerV2()+overlays();bind();if(route==='/search')updateSearch('');setupMotion();bindLuxuryDrawer();bindDesktopHeader();}
function overlays(){return `<div class="drawer-backdrop" data-close></div><aside class="drawer" id="drawer" aria-label="Shopping bag"><div class="drawer-head"><h2>Bag</h2><button class="icon-btn" data-close aria-label="Close bag">×</button></div><div class="drawer-items" id="drawer-items">${cartContent()}</div></aside><div class="modal-backdrop" data-modal-close></div><section class="modal" id="modal" role="dialog" aria-modal="true" aria-label="Quick view"></section><div class="toast" role="status" aria-live="polite"></div>`}
function bind(){document.querySelectorAll('[data-link]').forEach(a=>a.addEventListener('click',e=>{let href=a.getAttribute('href');if(href.startsWith('#'))return;e.preventDefault();history.pushState({},'',href);document.body.dataset.route=href;window.scrollTo(0,0);location.reload()}));document.querySelectorAll('[data-cart]').forEach(x=>x.onclick=openCart);document.querySelectorAll('[data-close]').forEach(x=>x.onclick=closeCart);document.querySelectorAll('[data-menu]').forEach(x=>x.onclick=()=>document.querySelector('#menu').classList.toggle('open'));document.querySelectorAll('[data-search]').forEach(x=>x.onclick=()=>{history.pushState({},'','/search');location.reload()});document.querySelectorAll('[data-wishlist]').forEach(x=>x.onclick=()=>{history.pushState({},'','/wishlist');location.reload()});document.querySelectorAll('[data-add]').forEach(x=>x.onclick=()=>add(x.dataset.add,Number(document.querySelector('#pdp-qty')?.textContent||1)));document.querySelectorAll('[data-wish]').forEach(x=>x.onclick=()=>wish(x.dataset.wish));document.querySelectorAll('[data-quick]').forEach(x=>x.onclick=()=>quick(x.dataset.quick));document.querySelectorAll('[data-cart-qty]').forEach(x=>x.onclick=()=>change(x.dataset.cartQty,+x.dataset.change));document.querySelectorAll('[data-remove]').forEach(x=>x.onclick=()=>remove(x.dataset.remove));document.querySelectorAll('[data-pdp-qty]').forEach(x=>x.onclick=()=>{let el=document.querySelector('#pdp-qty');el.textContent=Math.max(1,+el.textContent+(+x.dataset.pdpQty))});document.querySelectorAll('[data-feature]').forEach(x=>x.onclick=()=>feature(+x.dataset.feature));document.querySelectorAll('[data-mood]').forEach(x=>x.onclick=()=>mood(+x.dataset.mood));document.querySelectorAll('[data-slide]').forEach(x=>x.onclick=()=>showSlide(+x.dataset.slide));document.querySelector('[data-slide-next]')?.addEventListener('click',()=>showSlide(slide+1));document.querySelector('[data-slide-prev]')?.addEventListener('click',()=>showSlide(slide-1));document.querySelector('[data-sort]')?.addEventListener('change',e=>{let list=[...products];if(e.target.value==='az')list.sort((a,b)=>a.name.localeCompare(b.name));document.querySelector('#shop-grid').innerHTML=list.map(productCard).join('');bind()});document.querySelector('[data-search-input]')?.addEventListener('input',e=>updateSearch(e.target.value));document.querySelector('[data-contact]')?.addEventListener('submit',formSubmit);document.querySelector('[data-checkout]')?.addEventListener('submit',formSubmit);document.querySelector('[data-newsletter]')?.addEventListener('submit',e=>{e.preventDefault();e.target.reset();toast('Thank you for joining the season.')});}
function updateHeader(){document.querySelector('.header')?.replaceWith(document.createRange().createContextualFragment(header()).querySelector('.header'));}function add(slug,qty=1){let row=cart.find(i=>i.slug===slug);row?row.qty+=qty:cart.push({slug,qty});persist();render();toast('Added to your bag.');openCart();}function change(slug,n){let row=cart.find(i=>i.slug===slug);if(!row)return;row.qty+=n;if(row.qty<1)cart=cart.filter(i=>i.slug!==slug);persist();render()}function remove(slug){cart=cart.filter(i=>i.slug!==slug);persist();render()}function wish(slug){wishes=wishes.includes(slug)?wishes.filter(x=>x!==slug):[...wishes,slug];persist();render();toast(wishes.includes(slug)?'Saved to your wishlist.':'Removed from your wishlist.')}function openCart(){document.querySelector('.drawer').classList.add('open');document.querySelector('.drawer-backdrop').classList.add('open')}function closeCart(){document.querySelector('.drawer').classList.remove('open');document.querySelector('.drawer-backdrop').classList.remove('open')}function quick(slug){let p=bySlug(slug),m=document.querySelector('#modal');m.innerHTML=`<button class="icon-btn" data-modal-close style="float:right">×</button><div class="quickview"><img src="${p.image}" alt="${p.name}"/><div><p class="eyebrow">${p.notes}</p><h2>${p.name}</h2><p>${p.description}</p><p>Extrait de Parfum · 50 ML</p><button class="btn" data-add="${p.slug}">Add to Bag</button></div></div>`;m.classList.add('open');document.querySelector('.modal-backdrop').classList.add('open');document.querySelectorAll('[data-modal-close]').forEach(x=>x.onclick=()=>{m.classList.remove('open');document.querySelector('.modal-backdrop').classList.remove('open')});m.querySelector('[data-add]').onclick=()=>add(p.slug)}function feature(i){let p=products[i],el=document.querySelector('#feature');el.querySelector('.feature-image img').src=p.image;el.querySelector('.feature-image img').alt=p.name;el.querySelector('.feature-no').textContent=`${String(i+1).padStart(2,'0')} — 06`;el.querySelector('.notes').textContent=p.notes;el.querySelector('h3').textContent=p.name;el.querySelector('h4').textContent=p.subtitle;el.querySelector('.feature-details>p:not(.notes)').textContent=p.description;el.querySelector('.text-link').href='/product/'+p.slug;el.querySelector('.text-link').textContent='Explore '+p.name;el.querySelectorAll('[data-feature]').forEach((x,n)=>x.classList.toggle('active',n===i))}function mood(i){activeMood=i;let p=products[i],el=document.querySelector('.mood-visual');el.querySelector('img').src=p.image;el.querySelector('img').alt=p.name;el.querySelector('h3').textContent=p.name;el.querySelector('p').textContent=p.character;document.querySelectorAll('[data-mood]').forEach((x,n)=>x.classList.toggle('active',n===i))}function showSlide(i){slide=(i+3)%3;document.querySelectorAll('.hero-slide').forEach((x,n)=>x.classList.toggle('active',n===slide));document.querySelectorAll('.dot').forEach((x,n)=>x.classList.toggle('active',n===slide))}function updateSearch(q){let term=q.toLowerCase();let results=products.filter(p=>[p.name,p.mood,p.notes,p.character].join(' ').toLowerCase().includes(term));document.querySelector('#search-results').innerHTML=results.length?results.map(productCard).join(''):empty('No fragrances found.','Explore all fragrances','/shop');bind()}function formSubmit(e){e.preventDefault();let valid=[...e.currentTarget.querySelectorAll('[required]')].every(i=>i.value.trim()&&i.checkValidity());let status=e.currentTarget.querySelector('.form-status');if(!valid){status.className='form-status error';status.textContent='Please complete the required fields.';return}status.className='form-status success';status.textContent='Thank you. Your message has been received.';e.currentTarget.reset()}function toast(msg){let t=document.querySelector('.toast');if(!t)return;t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2500)}
function showSlide(i){const slides=document.querySelectorAll('.banner-slide');if(!slides.length)return;slide=(i+slides.length)%slides.length;slides.forEach((x,n)=>x.classList.toggle('active',n===slide));document.querySelectorAll('.banner-dots button').forEach((x,n)=>x.classList.toggle('active',n===slide));}
function stage(i){const p=products[i],el=document.querySelector('#collection-stage');if(!el)return;el.style.setProperty('--stage',p.accent);el.querySelector('.stage-number').textContent=`${String(i+1).padStart(2,'0')} / 06`;el.querySelector('.notes').textContent=p.notes;el.querySelector('h2').textContent=p.name;el.querySelector('h3').textContent=p.subtitle;el.querySelector('.stage-description').textContent=p.description;el.querySelector('.stage-copy .text-link').href='/product/'+p.slug;el.querySelector('.stage-copy .text-link').textContent='Explore '+p.name;const image=el.querySelector('.stage-product img');image.style.opacity='0';setTimeout(()=>{image.src=p.image;image.alt=p.name;image.style.opacity='1'},160);el.querySelectorAll('[data-stage]').forEach((x,n)=>x.classList.toggle('active',n===i));}
function ritu(i){const p=products[i],el=document.querySelector('.ritu-product');if(!el)return;el.style.setProperty('--ritu',p.accent);const image=el.querySelector('img');image.style.opacity='0';setTimeout(()=>{image.src=p.image;image.alt=p.name;image.style.opacity='1'},150);el.querySelector('h3').textContent=p.name;el.querySelector('.ritu-caption>p:not(.eyebrow)').textContent=p.character;el.querySelector('.inline-link').href='/product/'+p.slug;document.querySelectorAll('[data-ritu]').forEach((x,n)=>x.classList.toggle('active',n===i));}
function setupMotion(){document.querySelectorAll('[data-stage]').forEach(x=>x.onclick=()=>stage(+x.dataset.stage));document.querySelectorAll('[data-ritu]').forEach(x=>x.onclick=()=>ritu(+x.dataset.ritu));let revealObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('is-visible')}),{threshold:.16});document.querySelectorAll('.reveal,.reveal-grid,.season-step').forEach(el=>revealObserver.observe(el));let seasonObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){document.querySelectorAll('.season-step').forEach(x=>x.classList.remove('active'));e.target.classList.add('active');if(+e.target.dataset.season===5)document.querySelector('.season-final-v2')?.classList.add('show')}}),{threshold:.75});document.querySelectorAll('.season-step').forEach(el=>seasonObserver.observe(el));const hero=document.querySelector('.banner-hero');if(hero){let startX=0;hero.addEventListener('touchstart',e=>startX=e.changedTouches[0].screenX,{passive:true});hero.addEventListener('touchend',e=>{let d=e.changedTouches[0].screenX-startX;if(Math.abs(d)>42)showSlide(slide+(d<0?1:-1))},{passive:true});hero.tabIndex=0;hero.addEventListener('keydown',e=>{if(e.key==='ArrowRight')showSlide(slide+1);if(e.key==='ArrowLeft')showSlide(slide-1)})}if(route==='/'&&!sessionStorage.getItem('tsr-loader'))bootLoader();}
function bootLoader(){sessionStorage.setItem('tsr-loader','1');const loader=document.createElement('div');loader.className='loader-v2';loader.innerHTML='<img src="/logo.png" alt=""/><span></span><strong>THE SIXTH RITU</strong><em>THE SEASON OF LUXURY</em>';document.body.append(loader);setTimeout(()=>loader.classList.add('exit'),1450);setTimeout(()=>loader.remove(),1900);}
function applyBannerSources(){const mobile=window.matchMedia('(max-width: 640px)').matches;document.querySelectorAll('.banner-slide').forEach(slideEl=>{const source=slideEl.querySelector('source');const image=slideEl.querySelector('img');if(!source||!image)return;if(!image.dataset.desktop)image.dataset.desktop=image.getAttribute('src');source.media='not all';image.src=mobile?source.getAttribute('srcset'):image.dataset.desktop;});}
document.head.insertAdjacentHTML('beforeend','<link rel="stylesheet" href="/mobile-drawer.css"><link rel="stylesheet" href="/desktop-header.css"><link rel="stylesheet" href="/desktop-logo-override.css"><link rel="stylesheet" href="/mobile-refinement.css">');render();applyBannerSources();window.addEventListener('resize',applyBannerSources);setInterval(()=>{if(route==='/')showSlide(slide+1)},4500);window.addEventListener('popstate',()=>location.reload());
function desktopNavLink(path,label){return `<a href="${path}" data-link class="header-nav-link ${route===path?'active':''}">${label}</a>`}
function headerV4(){const bagCount=cart.reduce((a,i)=>a+i.qty,0);const wishlistCount=wishes.length;const legacy=headerV3();const mobileDrawer=legacy.slice(legacy.indexOf('<aside'));return `<div class="announcement announce-v2 announce-v3"><span class="announce-side announce-left">✦ &nbsp; A HIGHER SEASON AWAITS</span><span class="announce-center"><b>✦</b> DISCOVER THE SIXTH RITU <i>·</i> THE SEASON OF LUXURY <b>✦</b></span><span class="announce-side announce-right">India <i>|</i> INR ₹⌄</span></div><header class="header header-v2 header-v3"><button class="icon-btn mobile-menu" data-menu aria-label="Open menu" aria-expanded="false" aria-controls="lux-menu">${icons.menu}</button><nav class="nav nav-v2 nav-v3 nav-v3-left" aria-label="Primary navigation">${desktopNavLink('/','Home')}${desktopNavLink('/shop','Shop')}${desktopNavLink('/collection','The Collection')}${desktopNavLink('/about','Our Story')}</nav><a class="brand brand-v2 brand-v3" href="/" data-link><img src="/logo.png" alt="The Sixth Ritu"/></a><div class="header-right-v3"><nav class="nav nav-v2 nav-v3 nav-v3-right" aria-label="Secondary navigation">${desktopNavLink('/the-sixth-ritu','The Sixth Ritu')}${desktopNavLink('/contact','Contact')}</nav><span class="header-rule-v3" aria-hidden="true"></span><div class="tools tools-v3"><button class="icon-btn header-action" data-search aria-label="Search">${icons.search}</button><a href="/account" data-link class="icon-btn header-action" aria-label="Account">${icons.user}</a><button class="icon-btn header-action" data-wishlist aria-label="Wishlist">${icons.heart}${wishlistCount?`<span class="header-count">${wishlistCount}</span>`:''}</button><button class="icon-btn header-action" data-cart aria-label="Bag">${icons.bag}<span class="header-count">${bagCount}</span></button></div></div></header>${mobileDrawer}`}
function headerV2(){return headerV4()}
function bindLuxuryDrawer(){const drawer=document.querySelector('#lux-menu');const opener=document.querySelector('[aria-controls="lux-menu"]');if(!drawer||!opener)return;const closer=drawer.querySelector('[data-menu-close]');const focusable=()=>[...drawer.querySelectorAll('a[href],button:not([disabled])')];const setOpen=(open,restore=true)=>{drawer.classList.toggle('open',open);drawer.setAttribute('aria-hidden',String(!open));opener.setAttribute('aria-expanded',String(open));document.body.classList.toggle('lux-drawer-lock',open);if(open)requestAnimationFrame(()=>closer?.focus());else if(restore)requestAnimationFrame(()=>opener.focus())};opener.onclick=()=>setOpen(!drawer.classList.contains('open'));closer.onclick=()=>setOpen(false);drawer.querySelectorAll('.lux-drawer-nav a,.drawer-secondary a').forEach(linkEl=>linkEl.addEventListener('click',()=>setOpen(false,false)));drawer.querySelector('[data-drawer-bag]')?.addEventListener('click',()=>{setOpen(false,false);setTimeout(openCart,100)});drawer.querySelectorAll('[data-social]').forEach(button=>button.addEventListener('click',()=>toast('Social channels are coming soon.')));drawer.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();setOpen(false);return}if(e.key==='Tab'){const items=focusable();if(!items.length)return;const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}}
function bindDesktopHeader(){if(!window.matchMedia('(min-width:1001px)').matches)return;const header=document.querySelector('.header-v3');const announcement=document.querySelector('.announce-v3');if(!header)return;if(window.tsrHeaderScroll)window.removeEventListener('scroll',window.tsrHeaderScroll);window.tsrHeaderScroll=()=>{const compact=window.scrollY>26;header.classList.toggle('scrolled',compact);announcement?.classList.toggle('is-scrolled',compact)};window.addEventListener('scroll',window.tsrHeaderScroll,{passive:true});window.tsrHeaderScroll()}
